def split_line(line):
    """Splits one line of comma-separated text into its fields.

    Double quotes group text so a comma inside them stays in the field.
    The quotes are dropped, and a doubled quote inside a quoted field
    stands for one quote character.
    """
    fields = []
    buf = []
    quoted = False
    i = 0
    while i < len(line):
        ch = line[i]
        if quoted:
            if ch == '"':
                if i + 1 < len(line) and line[i + 1] == '"':
                    buf.append('"')
                    i += 1
                else:
                    quoted = False
            else:
                buf.append(ch)
        elif ch == '"':
            quoted = True
        elif ch == ",":
            fields.append("".join(buf).strip())
            buf = []
        else:
            buf.append(ch)
        i += 1
    fields.append("".join(buf).strip())
    return fields

files.tests/test_csvline.py:
from csvline import split_line


def test_plain_fields():
    assert split_line("a,b,c") == ["a", "b", "c"]


def test_strips_spaces():
    assert split_line("a , b") == ["a", "b"]


def test_comma_inside_quotes():
    assert split_line('a,"b,c",d') == ["a", "b,c", "d"]


def test_address_in_quotes():
    assert split_line('Bob,"12 High St, Leeds"') == ["Bob", "12 High St, Leeds"]


def test_doubled_quote_is_one_quote():
    assert split_line('a,"say ""hi""",b') == ["a", 'say "hi"', "b"]

